#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    long long numberOfPairs(std::vector<int>& nums) {
        std::vector<int> vals;
        vals.reserve(nums.size());
        for (int x : nums) vals.push_back(std::abs(x));
        std::sort(vals.begin(), vals.end());

        long long ans = 0;
        int n = vals.size();
        for (int i = 0; i < n; ++i) {
            long long target = 2LL * vals[i];
            auto it = std::upper_bound(vals.begin(), vals.end(), target);
            int count = std::distance(vals.begin() + i + 1, it);
            ans += count;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long numberOfPairs(int[] nums) {
        int n = nums.length;
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) vals[i] = Math.abs(nums[i]);
        Arrays.sort(vals);

        long ans = 0;
        for (int i = 0; i < n; i++) {
            long target = 2L * vals[i];
            int low = i + 1, high = n;
            while (low < high) {
                int mid = (low + high) >>> 1;
                if (vals[mid] <= target) {
                    low = mid + 1;
                } else {
                    high = mid;
                }
            }
            ans += (low - 1 - i);
        }
        return ans;
    }
}

